import { course } from './build.js';
const G='https://hosa.org/wp-content/uploads/2026/10/MM-26-27-Updated-10.17.pdf';
const N='https://www.nist.gov/pml/owm/metric-si/si-units';
const P='https://openstax.org/books/prealgebra-2e/pages/6-5-solve-proportions-and-their-applications';
const lessons=[];
function add(title,hook,sections,terms,example,mcqs,activity,source=P){
 lessons.push({title,hook,objectives:[`Solve problems involving ${title.toLowerCase()} with explicit units.`,'Explain why the selected operation and conversion factors preserve the quantity.','Check magnitude, assumptions, and final precision before reporting an answer.'],sections:[...sections.map(([h,p])=>[h,[p]]),['Reference concepts and practice',[{t:'table',head:['Concept','Meaning and use'],rows:terms},{t:'w',kind:'match',title:'Connect the mathematical idea to its meaning',pairs:terms.slice(0,5)},activity]],['Worked problem and interpretation',[{t:'example',prompt:example[0],steps:example[1],answer:example[2]}]]],terms,takeaways:terms.slice(0,3).map(([t,d])=>`${t}: ${d}`),mcqs,frq:{prompt:example[0]+' Show the setup with units, justify the operations, and explain one check or limitation.',rubric:example[3],model:example[1].join(' ')+' '+example[2]},sources:[['HOSA Medical Math 2026–27, October update and reference sheet',G],['NIST: SI units',N],Array.isArray(source)?source:['Mathematical reference',source]]});
}

add('Geometry, body surface area, and descriptive statistics','Two sets of measurements can have the same mean and very different variability. Likewise, doubling a length does not merely double an area. Dimensions and distribution both matter when interpreting a calculated value.',[
 ['Geometry preserves dimensions','Area measures two-dimensional extent and uses squared units; volume measures three-dimensional extent and uses cubed units. A rectangle has area length×width, and a rectangular prism has volume length×width×height. A circle has area πr², where r is radius, not diameter. A cylinder has volume πr²h. If a problem provides diameter, divide it by two before squaring. State the approximation for π when a numerical exercise requires it. These formulas are mathematical models; an irregular anatomical surface is not automatically a rectangle or cylinder. The current event’s reference sheet includes cubic-unit relationships and BSA formulas, while the broad essentials domain provides a place for supporting numerical reasoning. Do not assume that the blueprint assigns a separate percentage to geometry merely because these tools are useful.'],
 ['Scaling and unit conversion must agree','If every side of a rectangular shape doubles, area increases fourfold and volume eightfold. A 3 cm by 4 cm rectangle has area 12 cm², equal to 1,200 mm² because each centimeter contributes a factor of ten in two dimensions. A 3 cm by 4 cm by 5 cm prism has volume 60 cm³, equal to 60 mL. Converting its three lengths to millimeters first gives 30×40×50 = 60,000 mm³, the same volume. This independent route verifies the cubic factor. Do not apply a length conversion once to an area or volume. The final unit reveals how many dimensions the factor must cover. It also helps detect an accidental omission of a dimension from the formula.'],
 ['Body surface area is an estimate with a specified formula','The guideline gives BSA in m² as the square root of height in cm times weight in kg divided by 3,600. It also gives an imperial-input version using height in inches times weight in pounds divided by 3,131. Use the correct constant for the chosen input units; mixing centimeters with pounds and retaining either constant is invalid. For a mathematical example of 180 cm and 80 kg, the product is 14,400; dividing by 3,600 gives 4; the square root is 2 m². BSA is an estimate from a model, not a direct measurement of every skin surface. If a later exercise uses an amount per m², multiply by the estimated BSA with units and retain precision until the final requested step. This is a calculation exercise, not a clinical dosing recommendation.'],
 ['Center and spread answer different questions','The arithmetic mean is the sum of observations divided by their number. The median is the middle value after sorting, or the mean of the two central values when the count is even. The mode is the most frequent value and may be absent or nonunique. The range is maximum minus minimum. For 2, 4, and 6, the mean and median are 4 and the range is 4. For 0, 4, and 8, the mean and median remain 4 but the range is 8. An outlier can change the mean more than the median. None of these statistics independently proves that a measurement process is accurate, representative, or clinically acceptable. Always identify the variable, unit, sample size, and how the observations were obtained.'],
 ['Sample standard deviation step by step','The reference summary includes the sample standard-deviation formula. Compute the mean, subtract it from each observation, square each deviation, sum the squares, divide by n−1, and take the square root. For 2, 4, and 6, the deviations are −2, 0, and 2; the squared deviations sum to 8; dividing by 2 gives sample variance 4; taking the square root gives sample SD 2. A population formula uses n instead of n−1, so the problem’s wording matters. Variance has squared measurement units, while SD returns to the original unit. SD measures spread, not the accuracy of the mean or a guaranteed clinical range. A sample SD requires at least two observations. Keep intermediate precision, and do not discard negative deviations before squaring them.']
],[['Area','A two-dimensional measure expressed in squared units. Converting its unit requires squaring the corresponding linear conversion factor.'],['Volume','A three-dimensional measure expressed in cubed units. A linear scale change affects all three dimensions.'],['Radius','The distance from a circle’s center to its edge, equal to half the diameter. Using diameter as radius quadruples the calculated circular area.'],['BSA model','An estimated body surface area derived from height and weight using a specified formula. Input units must match the formula constant.'],['Mean','The sum of observations divided by their count. It describes center and can be influenced by unusually large or small observations.'],['Median','The central value after sorting observations, with the two central values averaged for an even count. It is not found from unsorted position.'],['Sample variance','The sum of squared deviations from the sample mean divided by n−1. Its units are the square of the original measurement unit.'],['Sample standard deviation','The square root of sample variance. It describes variability in the original unit and differs from the population formula’s denominator.']],['For invented measurements 2, 4, and 6 mL, calculate the mean and sample standard deviation. Separately calculate BSA for 180 cm and 80 kg using the event metric formula.',['The mean is (2+4+6)/3 = 4 mL.','Squared deviations sum to 8 mL²; divide by 3−1 = 2 to get variance 4 mL², then take the square root to obtain SD 2 mL.','BSA = √(180×80/3,600) = √4 = 2 m².'],'The statistical values describe the invented data, while BSA is a separate model estimate. Neither result alone establishes a clinical decision or the accuracy of the underlying measurements.',[['Center',['mean','4']],['Sample spread',['n−1','n-1','variance','2 ml']],['BSA units and formula',['3600','3,600','2','m²']]]],[['What is the area of a 3 cm by 5 cm rectangle?',['15 cm²','16 cm²','15 cm³','8 cm²'],'Multiply the two lengths and retain squared units.'],['A cylinder has radius 2 cm and height 5 cm. Using π=3.14, what is its volume?',['62.8 cm³','31.4 cm³','125.6 cm³','20 cm³'],'3.14×2²×5 = 62.8.'],['If a cube’s side doubles, its volume changes by what factor?',['8','2','4','6'],'Volume scales with the cube of length.'],['What is the median of 3, 9, 4, 8?',['6','4','7','9'],'Sort to 3,4,8,9 and average 4 and 8.'],['What is the range of 5, 7, 7, 12?',['7','5','12','31'],'Range is 12−5.'],['Which denominator is used for sample variance?',['n−1','n','n+1','The mean'],'Sample variance uses n−1.'],['For 160 cm and 81 kg, BSA using the metric formula is approximately what, to hundredths?',['1.90 m²','3.60 m²','1.60 m²','2.25 m²'],'√(160×81/3600)=√3.6≈1.8974, rounded to 1.90 m² as a measurement.'],['Which statistic returns variance to the original measurement unit?',['Standard deviation','Squared deviation','Sum of squares','Variance itself'],'Taking the square root restores the original unit.']],{t:'w',kind:'order',title:'Calculate sample standard deviation',steps:['Find the sample mean','Subtract the mean from each observation','Square each deviation','Add the squared deviations','Divide by n−1','Take the square root and report the original unit']},'https://openstax.org/books/introductory-statistics-2e/pages/2-7-measures-of-the-spread-of-the-data');

add('Dosage arithmetic for tablets, liquids, and reconstituted examples','The same mass can correspond to different volumes in two formulations. A label’s concentration is the bridge between the requested amount and the quantity to calculate.',[
 ['Separate amount, concentration, and quantity','An amount such as 150 mg describes mass. A concentration such as 50 mg per 5 mL describes mass relative to volume. The calculated quantity is the volume containing the stated mass. In an invented example, 150 mg × 5 mL/50 mg = 15 mL. The mg units cancel and mL remains. A common formula is desired amount divided by available amount times the associated quantity, but the formula is reliable only when the mass units match and the quantity belongs to the stated available amount. Do not divide 150 by 50 and report 3 mL while forgetting that 50 mg corresponds to 5 mL. The ratio 50 mg/5 mL is equivalent to 10 mg/mL, which provides an independent way to check.'],
 ['Solid-unit examples and formulation constraints','For an invented tablet labeled 25 mg per tablet, a mathematical amount of 75 mg corresponds to 3 tablets. The unit tablet acts as a count unit. A calculation can also produce a fraction, such as 1.5 tablets, but that number does not establish whether the real product can be divided. Formulation, scoring, stability, and the authorized order would matter in practice. This lesson does not make those determinations. If a problem asks only for the arithmetic, show the fractional quantity and the requested rounding without silently assuming a preparation technique. Capsules, extended-release products, and other forms are not interchangeable merely because the active ingredient mass matches. Mathematical equivalence is narrower than clinical or pharmaceutical interchangeability. Keep that distinction explicit when interpreting a result.'],
 ['Normalize units before applying the label','If the desired amount is 0.3 g and the teaching liquid contains 75 mg per 5 mL, convert 0.3 g to 300 mg first. Then 300 mg × 5 mL/75 mg = 20 mL. Alternatively, include the conversion factor in one chain: 0.3 g × 1,000 mg/g × 5 mL/75 mg. Both approaches produce the same unit cancellation. A result of 0.02 mL would signal that the gram-to-milligram relationship was mishandled. Estimate before calculating: 300 mg is four times the 75 mg in the label quantity, so the answer should be four times 5 mL. Never let a convenient calculator expression hide mismatched units. The correct arithmetic on incompatible numbers still produces an invalid answer.'],
 ['Reconstitution problems use the stated final concentration','A powder label in a teaching problem may state that adding a specified diluent produces a final concentration. The final solution volume need not equal the volume of diluent added because the powder and formulation can affect displacement. Use the stated final volume or final concentration, not an unsupported assumption that added water equals final solution volume. If an invented vial contains 600 mg and the problem states a final volume of 12 mL, its concentration is 50 mg/mL. If a separate amount of 125 mg is requested mathematically, the corresponding volume is 2.5 mL. The example does not instruct a real reconstitution process. Real products require their current directions, compatibility, handling, and professional verification. Here the purpose is to distinguish total mass, added volume, and final volume.'],
 ['Label changes and independent verification','Two bottles may show 100 mg/5 mL and 200 mg/5 mL. The second is twice as concentrated, so the volume for the same mass is half as large. A familiar previous volume cannot be carried forward without checking the new concentration. Verify the calculated quantity by multiplying it by concentration to reconstruct the requested mass. Also compare the answer with the label quantity and estimate its size. If a result requires more volume than the stated container holds, that may indicate a multi-container quantity or an error; the problem must supply enough context to decide. Do not invent an answer by changing the concentration. Explain uncertainty when data are inconsistent or incomplete, because recognizing an unsolvable setup is part of mathematical competence.']
],[['Desired amount','The quantity of active substance specified in the exercise, commonly expressed as mass. It is distinct from the volume or count needed to represent it.'],['Available amount','The mass associated with a stated label quantity, such as 50 mg in 5 mL. Both parts of the label ratio must be retained.'],['Unit quantity','The volume or count corresponding to the available amount. It may be milliliters, tablets, or another explicitly defined unit.'],['Normalized concentration','A ratio expressed per one denominator unit, such as 10 mg/mL. It can simplify calculations and provide a second check.'],['Final volume','The total solution volume after the described preparation. It is not automatically equal to the volume of diluent added.'],['Displacement','The contribution of a substance to final volume in a preparation. It is why powder reconstitution cannot always be modeled as diluent volume alone.'],['Formulation limitation','A practical property that arithmetic does not establish, such as whether a tablet may be split. Numerical equivalence is not authorization to manipulate a product.'],['Back-calculation','Multiplying the calculated volume or count by its concentration or strength to verify that it reproduces the requested amount.']],['An invented powder contains 600 mg and is described as yielding 12 mL final solution. Calculate the concentration and the volume containing 125 mg. Explain why diluent volume alone would be insufficient if final volume were not given.',['Concentration is 600 mg/12 mL = 50 mg/mL.','The quantity for 125 mg is 125 mg × 1 mL/50 mg = 2.5 mL.','Powder displacement can make final volume differ from added diluent volume, so the stated final volume or concentration is needed.'],'The mathematical result is 2.5 mL. Back-calculation gives 2.5×50 = 125 mg; it does not establish a real preparation or administration instruction.',[['Concentration',['50','mg/ml']],['Volume and check',['2.5','125']],['Final-volume distinction',['final','diluent','displacement']]]],[['A teaching tablet contains 20 mg. How many tablets correspond mathematically to 60 mg?',['3','0.33','6','30'],'60/20 = 3 tablets.'],['A liquid contains 40 mg/5 mL. What volume contains 24 mg?',['3 mL','0.6 mL','8.33 mL','30 mL'],'24×5/40 = 3 mL.'],['Convert 0.25 g before comparing it with an mg label.',['250 mg','25 mg','2.5 mg','2,500 mg'],'Multiply grams by 1,000.'],['A solution contains 80 mg in 4 mL. What is its concentration?',['20 mg/mL','320 mg/mL','0.05 mg/mL','84 mg/mL'],'Divide mass by volume.'],['If concentration doubles while desired mass stays fixed, volume does what?',['Halves','Doubles','Stays fixed','Quadruples'],'Volume equals mass divided by concentration.'],['Why can added diluent differ from final volume?',['The formulation can contribute volume','Mass and volume are identical','Every powder has zero displacement','The unit mL changes after mixing'],'Final volume must be stated or established by the provided formulation information.'],['A 150 mg amount is represented by 6 mL. Which concentration does that imply?',['25 mg/mL','900 mg/mL','0.04 mg/mL','15 mg/mL'],'150/6 = 25 mg/mL.'],['A calculation gives 1.5 tablets. What does the number establish?',['Only the mathematical count equivalent under the stated strength','That every tablet can safely be split','That capsules and tablets are interchangeable','That rounding to two is always appropriate'],'Formulation and clinical suitability are separate from arithmetic.']],{t:'w',kind:'sort',title:'Read the label quantities',buckets:['Mass amount','Concentration','Volume or count'],items:[['125 mg',0],['0.3 g',0],['50 mg/mL',1],['25 mg/tablet',1],['2.5 mL',2],['3 tablets',2]]});

add('Weight-based, daily, and body-surface-area calculations','A statement of mg/kg/day is not the same as mg/kg/dose. Missing that final word can multiply an answer even when the weight conversion and calculator arithmetic are correct.',[
 ['Read every denominator','A rate such as 12 mg/kg/day means twelve milligrams for each kilogram over an entire day. A rate of 12 mg/kg/dose means twelve milligrams for each kilogram at each administration in the mathematical scenario. Multiplying either by kilograms cancels kg, but the remaining time or dose unit differs. For an invented 20 kg subject, 12 mg/kg/day gives 240 mg/day. If the exercise divides that daily total into three equal quantities, each is 80 mg/dose. By contrast, 12 mg/kg/dose gives 240 mg/dose directly. The numerical coefficient and weight can be identical while the final answer differs threefold. Therefore write the full unit, including per day or per dose, before performing any multiplication.'],
 ['Convert body mass once and carry precision','Using the event approximation, 55 lb corresponds to 55/2.2 = 25 kg. A mixed pounds-and-ounces value must first become decimal pounds. When the converted kilogram value is not exact, retain its available precision through the remaining steps unless the problem specifically directs otherwise. Rounding weight early can alter the final amount, especially after multiplication by another factor. Do not convert the result back to pounds unless asked; repeated unnecessary conversions can compound approximation differences. A stated current weight and the correct unit are prerequisites for the arithmetic. A question using kilograms should not be answered with the same numeric value labeled pounds. Unit labels are part of the data, not decorations added after the calculation.'],
 ['Connect daily totals to formulation volume','Suppose an invented problem gives 18 mg/kg/day for 25 kg, divided into three equal quantities, with a teaching concentration of 30 mg/mL. First calculate 450 mg/day. Divide by three doses/day to obtain 150 mg/dose. Divide by 30 mg/mL to obtain 5 mL/dose. A single chain can show all cancellations, but the separate steps make the daily-versus-dose distinction visible. Check the result by reconstructing the daily amount: 5 mL/dose × 30 mg/mL × 3 doses/day = 450 mg/day. Dividing by 25 kg returns 18 mg/kg/day. This reverse calculation detects a missed division by the number of doses. The example is invented and evaluates unit reasoning, not an actual regimen.'],
 ['Ranges and maximums are constraints, not rounding rules','A teaching problem may provide a range such as 4–6 mg/kg/day and ask whether a stated total lies within it. Calculate both endpoints using the same weight and time basis, then compare the proposed total in matching units. If a separate maximum is supplied, it is another constraint. A value inside the weight-based range may still exceed that maximum. Do not assume the midpoint is the required answer unless the question requests it. Likewise, being inside a mathematical range does not establish clinical safety; the scenario’s supplied limits are the only basis for the exercise. In real practice other factors matter. The correct educational conclusion is that a number meets or does not meet the stated quantitative conditions, not that it is universally appropriate.'],
 ['BSA and event-specific precision','An amount expressed in mg/m² uses body surface area rather than body mass. Estimate BSA using the supplied formula and appropriate height and weight units, then multiply by the per-square-meter amount. For BSA 1.6 m² and a purely mathematical factor of 25 mg/m², the amount is 40 mg. Do not substitute kg into a denominator of m². If BSA was calculated rather than supplied, keep its unrounded value until the final step. The HOSA guideline includes a pediatric downward-rounding convention and a default nearest-whole rule, but each practice item here states its own requested precision. These are competition and classroom rules, not a universal method for real pediatric dosing. The final explanation should name both the calculation basis and the precision used.']
],[['Per kilogram per day','An amount scaled to body mass over a full day. A divided schedule requires a further division to obtain each mathematical dose.'],['Per kilogram per dose','An amount scaled to body mass for each dose. It is not automatically the same as a daily total.'],['Daily total','The sum of all quantities over a day. Its unit differs from a per-dose amount even when the numerical values happen to match.'],['Divided quantity','A daily total split into the stated number of equal parts. The number of doses must come from the problem rather than assumption.'],['Range endpoint','The lower or upper bound calculated from the supplied rate and weight. Both endpoints must use the same units as the proposed value.'],['Maximum constraint','A separately supplied upper limit that must also be checked. It is not removed by satisfying a different weight-based range.'],['BSA-based amount','A quantity obtained by multiplying an amount per square meter by a BSA estimate in square meters. Kilograms cannot replace square meters.'],['Precision policy','The explicit rounding instruction used for the exercise. A competition convention should not be generalized into unsupervised clinical practice.']],['An invented calculation uses 18 mg/kg/day for 55 lb, divided into three equal quantities. Using 2.2 lb/kg and 30 mg/mL, find mL per quantity and verify the daily total.',['55 lb × 1 kg/2.2 lb = 25 kg.','25 kg × 18 mg/kg/day = 450 mg/day; dividing by three gives 150 mg per quantity.','150 mg ÷ 30 mg/mL = 5 mL; 5×30×3 returns 450 mg/day.'],'The mathematical result is 5 mL per quantity. The full denominator mg/kg/day is essential; treating it as mg/kg/dose would triple the daily total.',[['Weight conversion',['25','2.2','kg']],['Daily and divided amounts',['450','150','three']],['Volume and verification',['5','30','verify','daily']]]],[['20 kg × 8 mg/kg/day equals what?',['160 mg/day','160 mg/dose regardless of schedule','2.5 mg/day','0.4 mg/kg'],'Kilograms cancel and the day denominator remains.'],['A 300 mg daily total is divided into four equal quantities. Each is what?',['75 mg','1,200 mg','100 mg','0.0133 mg'],'300/4 = 75.'],['Using 2.2 lb/kg, 66 lb equals what?',['30 kg','145.2 kg','33 kg','3 kg'],'66/2.2 = 30.'],['For 15 kg, a supplied range of 2–4 mg/kg/day gives what daily range?',['30–60 mg/day','2–4 mg/day','7.5–15 mg/day','30–60 mg/dose regardless of schedule'],'Multiply both endpoints by 15 kg.'],['A BSA of 1.8 m² times 20 mg/m² gives what?',['36 mg','11.1 mg','360 mg','36 mg/kg'],'Square meters cancel.'],['Which error triples a daily amount divided into three parts?',['Treating mg/kg/day as mg/kg/dose','Converting pounds to kilograms correctly','Dividing the daily total by three','Checking the final concentration'],'Using the daily rate at each of three doses triples the total.'],['A mathematical 90 mg quantity at 45 mg/mL corresponds to what volume?',['2 mL','0.5 mL','4,050 mL','20 mL'],'90/45 = 2.'],['A value meets the supplied weight-based range but exceeds a supplied maximum. What follows?',['It fails the full set of stated constraints','The maximum can be ignored','The range guarantees universal safety','Round upward until it fits'],'All supplied constraints must be satisfied.']],{t:'w',kind:'order',title:'Keep daily and per-dose units separate',steps:['Read whether the factor is per day or per dose','Convert the stated weight to kilograms','Calculate the amount on the stated time basis','Divide a daily total into the specified number of quantities','Convert mass to volume using the stated concentration','Reconstruct the daily total to check the answer']});

add('Numerical essentials, proportions, and final-answer precision','A calculator can return many digits from an incorrect setup. The first skill is deciding what the numbers represent, and the last is reporting only the precision the problem requests.',[
 ['The event and the problem-solving contract','The October 2026 Medical Math guideline assigns 5% to mathematical essentials, 30% to measurements and conversions, 35% to drug dosage and intravenous solutions, and 30% to dilutions, solutions, and concentrations. At least half of computation problems involve conversions. The official written event uses grid-in or write-in numerical responses rather than the multiple-choice practice format used here. Its reference summary establishes conversion conventions but may not be used during testing. These lessons use invented quantitative examples to teach mathematics; they do not authorize preparation or administration of medication. For each problem identify the requested quantity, given information, units, assumptions, and rounding instruction. Write the target unit before calculating. That small step helps distinguish an answer in milligrams from one in milliliters or minutes.'],
 ['Fractions, decimals, and percentages represent the same quantity','A fraction expresses a part relative to a whole or a division. Convert 3/4 to a decimal by dividing 3 by 4, giving 0.75; as a percentage it is 75%. A mixed number such as 2 1/2 is 2.5, not 2.1. To add fractions, use a common denominator; to multiply, multiply numerators and denominators; to divide by a fraction, multiply by its reciprocal. Parentheses preserve the intended order of operations. For example, (12 + 8)/4 is 5, while 12 + 8/4 is 14. A percentage is per hundred: 6% is 0.06 as a pure number. Whether a concentration percentage describes mass per volume or another basis must still be specified. The symbol alone does not settle the units.'],
 ['Ratios and proportions require consistent orientation','A ratio compares quantities, and a proportion states that two ratios are equal. If a teaching stock contains 40 mg in 5 mL, then 40 mg/5 mL = 80 mg/x mL leads to x = 10 mL. Both ratios place mass above volume. Reversing only one side destroys the correspondence even if cross-multiplication is performed correctly. Dimensional analysis expresses the same relationship as 80 mg × 5 mL/40 mg. Milligrams cancel, leaving milliliters. Direct proportionality means doubling one quantity doubles the other when the ratio remains constant. Inverse proportionality appears when a fixed volume is delivered faster: doubling the rate halves the duration. Identify what remains fixed before choosing either relationship. Not every relationship, such as Celsius-to-Fahrenheit conversion, is a simple ratio.'],
 ['Rounding, zeros, and the competition convention','Keep intermediate results unrounded whenever possible and round the final answer as directed. To round 7.346 to hundredths, inspect the thousandths digit: 6 raises the hundredths digit, producing 7.35. To round to tenths, inspect the hundredths digit instead, producing 7.3. The current HOSA guideline defaults to the nearest whole number unless otherwise indicated and includes a special downward-rounding statement for pediatric dosage examples. Treat that as an event convention, not a universal clinical dosing rule. This course states a precision for its calculation exercises. Values below one should have a leading zero, such as 0.5. Avoid an unnecessary trailing zero on a whole-number dose expression. Numerical precision and safe notation are related but different: the answer must both meet the task and remain unambiguous.'],
 ['Estimate, verify, and explain','Before using a calculator, estimate the magnitude. If 40 mg corresponds to 5 mL, a request for 20 mg should require less than 5 mL, not more. After calculating, substitute the result back into the original relationship. An answer of 2.5 mL gives 40 mg/5 mL × 2.5 mL = 20 mg. A second method is valuable only if it is genuinely independent; repeating the same incorrect setup does not add assurance. In an essay explanation, state the relationship, unit cancellation, result, and reasonableness check. If information is missing, identify it rather than guessing. A mathematically correct volume still does not establish whether a medication order or formulation is clinically appropriate. The lesson’s focus is quantitative consistency under the explicitly stated assumptions.']
],[['Numerator','The upper part of a fraction, interpreted with the denominator. In a rate such as mg/mL it names the quantity supplied for each denominator unit.'],['Reciprocal','The inverted form of a nonzero fraction. Multiplying by a reciprocal performs division, but its units must also invert.'],['Proportion','An equality between two ratios. Corresponding units must occupy corresponding positions on both sides before cross-multiplication is valid.'],['Direct variation','A relationship in which quantities scale together at a fixed ratio. Doubling volume doubles solute amount when concentration stays constant.'],['Inverse variation','A relationship in which one quantity falls as another rises while their product remains fixed, such as duration and rate for a fixed volume.'],['Final rounding','Applying the requested precision after completing the calculation. Early rounding can propagate error through later multiplication or division.'],['Leading zero','A zero before the decimal in a value below one, such as 0.5. It makes the decimal value easier to recognize.'],['Reasonableness check','A comparison of the result with expected direction, magnitude, and units. It can reveal a reversed ratio even when calculator arithmetic is accurate.']],['An invented solution contains 40 mg in 5 mL. Find the volume containing 18 mg, reporting to the nearest hundredth of a milliliter, and explain how to check it.',['Set up 18 mg × 5 mL/40 mg; the mg units cancel.','The unrounded result is 2.25 mL, which already has the requested precision.','Check by multiplying 2.25 mL × 8 mg/mL = 18 mg; the volume is less than 5 mL as expected.'],'The mathematical answer is 2.25 mL under the given concentration. This example evaluates proportional reasoning, not the clinical suitability of a dose.',[['Correct proportional setup',['18','5','40','ratio']],['Correct result and units',['2.25','ml']],['Independent check',['8','check','less','18']]]],[['What is 3/8 as a decimal?',['0.375','0.38 exactly','0.625','3.8'],'Divide 3 by 8; 0.38 would be a rounded value.'],['What is 2 3/4 as a decimal?',['2.75','2.34','2.25','0.275'],'The fraction 3/4 equals 0.75.'],['What is 12% as a decimal?',['0.12','1.2','12','0.012'],'Percent means divide by 100.'],['Round 6.784 to the nearest hundredth.',['6.78','6.79','6.8','6.7'],'The thousandths digit is 4, so the hundredths digit stays unchanged.'],['For a fixed volume, doubling the flow rate does what to duration?',['Halves it','Doubles it','Leaves it unchanged','Squares it'],'Duration equals volume divided by rate.'],['A stock has 10 mg per 2 mL. What volume contains 25 mg?',['5 mL','1.25 mL','12.5 mL','0.8 mL'],'25×2/10 = 5 mL.'],['Which notation includes a leading zero?',['0.4',' .4','4.0','40'],'A leading zero precedes the decimal in a value below one.'],['Which expression equals 5?',['(12 + 8)/4','12 + 8/4','12/(8 + 4)','12 + (8/4)'],'Parentheses require addition before division.']],{t:'w',kind:'order',title:'Build a defensible solution',steps:['Identify the requested quantity and unit','List the given values and assumptions','Arrange ratios so unwanted units cancel','Calculate without rounding intermediate values','Round the final result as requested','Check magnitude and substitute into the original relationship']});

add('Metric mass, length, and volume conversions','A change from milligrams to micrograms changes the numerical value by a thousand while leaving the physical quantity unchanged. Unit conversion preserves an amount; it does not create more material.',[
 ['Prefixes express powers of ten','Metric prefixes modify a unit by a defined power of ten. Kilo- means one thousand, centi- one hundredth, milli- one thousandth, and micro- one millionth of the base unit. In the event reference, 1 kg = 1,000 g, 1 g = 1,000 mg, and 1 mg = 1,000 mcg. A 0.6 mg quantity is therefore 600 mcg, not 0.0006 mcg. The smaller unit requires a larger numerical count to represent the same amount. Before calculating, predict that direction. A conversion factor is a ratio of equal quantities, so it equals one physically. Multiplying 0.6 mg by 1,000 mcg/1 mg changes the unit expression without changing the amount. The unit in the denominator cancels the starting unit.'],
 ['Build chains instead of memorizing isolated decimal moves','To convert 0.0025 kg to mg, write 0.0025 kg × 1,000 g/kg × 1,000 mg/g = 2,500 mg. The chain makes the two factors visible. A decimal-shifting shortcut can be efficient, but it should be backed by the relationship so that skipped prefixes do not cause errors. For length, 1 m = 100 cm = 1,000 mm and 1 cm = 10 mm. Thus 3.2 cm is 32 mm, while 32 mm is 0.032 m. Do not treat every prefix step as a factor of one thousand: centi- to milli- is a factor of ten. Symbols are case-sensitive in formal SI usage. Use a clear L for liter and mL for milliliter to reduce confusion with the numeral one.'],
 ['Volume and cubic dimensions','The reference sheet includes 1 L = 1,000 mL and 1 cm³ = 1 mL. A cubic centimeter describes a geometric volume, while a milliliter describes the same volume in a different unit form. Converting cubic units requires cubing the linear factor. Since 1 cm = 10 mm, 1 cm³ = 10×10×10 = 1,000 mm³. Since 1 m = 100 cm, 1 m³ = 1,000,000 cm³, not 100 cm³. A linear conversion applied only once is a common error. The exponent belongs to the entire unit factor. A cube with sides of 2 cm has volume 8 cm³, equivalent to 8 mL; doubling the side length increases volume eightfold, not twofold. This is dimensional reasoning, not merely a memorized table.'],
 ['Mass is not volume without another relationship','Milligrams measure mass and milliliters volume. You cannot convert between them using only a metric prefix. A density or concentration is required. If an invented liquid contains 12 mg/mL, then 36 mg corresponds to 3 mL; another liquid with a different concentration gives another volume. The familiar approximation that 1 mL of water has a mass near 1 g under ordinary conditions is not a universal rule for all liquids or solutions. Likewise, a powder’s mass does not specify the final volume after dissolving. Read the label or problem for the relevant relationship. If it is missing, the correct conclusion is that the conversion cannot be completed from the supplied information. Distinguishing dimensions prevents a plausible-looking but fundamentally invalid calculation.'],
 ['Use scientific notation and checks for very small values','Scientific notation writes a quantity as a coefficient multiplied by a power of ten. For example, 0.00045 g = 4.5×10^-4 g = 0.45 mg = 450 mcg. The coefficient and exponent together preserve the number. When multiplying powers of ten, add exponents; when dividing, subtract them. A negative exponent does not make the quantity negative. It describes a small positive magnitude. Keep the original unit attached until the conversion is complete. Then reverse the conversion as a check: 450 mcg × 1 mg/1,000 mcg = 0.45 mg. If the result differs by a thousand, revisit the factor orientation. In a multi-step problem, carrying units through every line is more reliable than remembering where a decimal point was moved several steps earlier.']
],[['Kilogram','A mass unit equal to 1,000 grams. Converting kilograms to grams increases the numerical value because the gram is smaller.'],['Milligram','One thousandth of a gram. It is a mass unit and cannot be converted directly to milliliters without concentration or density information.'],['Microgram','One thousandth of a milligram. The event reference uses mcg; its numerical relationship to mg is a factor of 1,000.'],['Milliliter','One thousandth of a liter and equal in volume to one cubic centimeter. It is not automatically equal to one milligram.'],['Cubic conversion','A conversion in which the linear scale factor is raised to the third power. Ten millimeters per centimeter yields 1,000 cubic millimeters per cubic centimeter.'],['Conversion factor','A ratio of equal quantities that preserves the underlying amount while changing its unit representation. Orientation is chosen to cancel the starting unit.'],['Density','Mass per volume of material. It can connect mass and volume, but its value depends on the material and conditions.'],['Scientific notation','A coefficient multiplied by a power of ten. It makes very small or large values easier to track without changing the represented quantity.']],['Convert 0.0036 g to micrograms and 2.4 cm³ to cubic millimeters. Explain why the second conversion uses a cubed factor.',['0.0036 g × 1,000 mg/g × 1,000 mcg/mg = 3,600 mcg.','2.4 cm³ × (10 mm/1 cm)³ = 2,400 mm³.','Volume has three length dimensions, so the linear factor applies in each dimension.'],'Both conversions preserve the original physical quantity. The numerical values grow because the requested units are smaller, and the cubic conversion requires a factor of 1,000 rather than ten.',[['Mass chain',['3600','3,600','1000','mcg']],['Cubic factor',['cube','third','1000','1,000']],['Result and preservation',['2400','2,400','same','preserv']]]],[['Convert 0.45 mg to mcg.',['450 mcg','45 mcg','0.00045 mcg','4,500 mcg'],'Multiply by 1,000 mcg/mg.'],['Convert 2.8 L to mL.',['2,800 mL','280 mL','0.0028 mL','28,000 mL'],'One liter equals 1,000 mL.'],['Convert 75 mm to cm.',['7.5 cm','750 cm','0.75 cm','75 cm'],'There are ten millimeters per centimeter.'],['How many mm³ equal 3 cm³?',['3,000 mm³','30 mm³','300 mm³','0.003 mm³'],'Cube the linear factor of ten.'],['Convert 1.2 kg to mg.',['1,200,000 mg','1,200 mg','12,000 mg','120,000 mg'],'Two factors of 1,000 connect kg to mg.'],['Which information permits conversion from mg to mL?',['A concentration in mg/mL','A length in cm','A time in minutes','A mass prefix alone'],'Mass per volume connects the dimensions.'],['What is 4.5×10^-4 g in mg?',['0.45 mg','4.5 mg','45 mg','0.0045 mg'],'Multiply grams by 1,000 to obtain milligrams.'],['Which volume equals 1 mL?',['1 cm³','1 mm³','1 m³','100 cm³'],'The event reference equates mL and cubic centimeters.']],{t:'w',kind:'mathlab',mode:'conversion',title:'Explore unit conversion factors'},N);

add('Household measures, temperature, and clock arithmetic','An ounce can refer to mass or fluid volume. A temperature conversion includes an offset, and clock minutes are counted in sixties. These are three reasons that ordinary decimal shortcuts can fail.',[
 ['Use the event’s stated approximations','The HOSA reference summary uses 1 kg = 2.2 lb, 1 lb = 16 oz, 1 inch = 2.54 cm, and 1 foot = 12 inches. For household fluid measures it uses 1 cup = 240 mL, 1 fluid ounce = 30 mL, 1 tablespoon = 15 mL, and 1 teaspoon = 5 mL. These are the competition conventions, even when a more exact national measurement definition differs slightly. Use the supplied or official factor consistently rather than mixing approximations. The reference’s ounce in a volume table must be interpreted as a fluid-volume unit, while the ounce in a weight table is a mass unit. The shared word does not authorize direct conversion between mass and volume. A problem’s context must identify which dimension is intended.'],
 ['Convert mixed units in a deliberate sequence','For an invented mass of 7 lb 8 oz, first convert ounces to pounds: 8/16 = 0.5 lb, giving 7.5 lb. Then divide by 2.2 lb/kg to obtain approximately 3.409 kg. If the question asks for hundredths, report 3.41 kg after the final calculation. Do not read 7 lb 8 oz as 7.8 lb. For height, 5 ft 6 in becomes 5×12 + 6 = 66 in; multiplying by 2.54 gives 167.64 cm. For household fluid volume, 2 tablespoons equal 30 mL under the event factors. A household spoon in real life is not a calibrated measuring device; these are mathematical equivalences for exam problems, not instructions to measure medication with kitchen utensils.'],
 ['Temperature scales require an offset','The event formulas are °C = (°F − 32)×5/9 and °F = °C×9/5 + 32. The subtraction or addition of 32 accounts for different zero points, while the ratio accounts for different interval sizes. For 86°F, subtract 32 to obtain 54, then multiply by 5/9 to obtain 30°C. Applying 5/9 before subtracting 32 produces a different, incorrect result. For a temperature difference rather than an absolute temperature, the offset cancels: a rise of 9°F corresponds to a rise of 5°C. Do not add 32 to a difference. Distinguish a reading of 10°C from an increase of 10°C. The same number has different mathematical meaning depending on whether it represents a location on a scale or an interval.'],
 ['Elapsed time uses sixty minutes per hour','A duration of 2 hours 30 minutes is 2.5 hours, not 2.30 hours. Convert minutes by dividing by 60. Conversely, 2.3 hours is 2 hours plus 0.3×60 = 18 minutes. The 24-hour clock identifies a time of day, not a duration. An event beginning at 22:40 and lasting 2 hours 35 minutes ends at 01:15 the next day. Carry minutes into hours whenever they reach 60 and carry hours past midnight into the next day. For subtraction, crossing midnight may be easier by splitting the interval: from 23:20 to midnight is 40 minutes, then from midnight to 01:10 is 70 minutes, totaling 110 minutes. A four-digit clock display is not an ordinary base-ten number.'],
 ['Choose the factor from the actual problem','The reference summary includes an approximate drops-to-volume relationship, but an intravenous calculation may provide a specific drop factor for the tubing. Use that stated factor rather than automatically substituting a general household approximation. Similarly, a problem can explicitly direct a conversion or precision that governs the example. Read the complete wording before starting. When an answer combines converted duration with a start time, retain precision through the duration calculation and round at the requested reporting stage. Check that the finish time is later by the calculated interval, including the next-day marker where relevant. A correct numeric time without the day transition can still be misleading in prose. The goal is to preserve both the quantitative interval and its temporal context.']
],[['Mass ounce','One sixteenth of a pound in the event’s weight relationship. It is not the same dimension as a fluid ounce.'],['Fluid ounce','A volume measure approximated as 30 mL in the event reference. Its relationship to mass depends on the material.'],['Mixed-unit conversion','Combining quantities into one unit before applying another conversion, such as converting feet and inches entirely to inches.'],['Temperature offset','The 32-degree adjustment between Celsius and Fahrenheit zero points. It applies to absolute readings, not directly to temperature differences.'],['Decimal hour','An hour expressed with a decimal fraction. The fractional part is multiplied by 60 to obtain minutes.'],['24-hour time','A clock notation for time of day. It is not a decimal number that can be added without carrying minutes and days correctly.'],['Drop factor','The specified number of drops per milliliter for a calculation. A problem-specific tubing factor overrides a generic approximation.'],['Approximate equivalence','A standardized factor used for consistency in an exercise or event. Mixing it with a different approximation can create avoidable discrepancies.']],['Using the event factors, convert 5 ft 8 in to centimeters. Then find the finish time for an invented 2.75-hour process beginning at 22:30.',['5×12 + 8 = 68 inches; 68×2.54 = 172.72 cm.','2.75 hours is 2 hours plus 0.75×60 = 45 minutes.','22:30 plus 2 hours 45 minutes is 01:15 the next day.'],'The answers are 172.72 cm and 01:15 on the following day. Mixed length units must be combined before conversion, and decimal hours must be converted to minutes before clock addition.',[['Length setup',['68','2.54','172.72']],['Fractional hour',['45','0.75','60']],['Clock and day',['01:15','0115','next','following']]]],[['Using HOSA factors, 3 tablespoons equal what volume?',['45 mL','15 mL','30 mL','90 mL'],'Three times 15 mL equals 45 mL.'],['Using 2.2 lb/kg, 44 lb equals what mass?',['20 kg','96.8 kg','22 kg','2 kg'],'Divide pounds by 2.2.'],['Convert 104°F to Celsius.',['40°C','72°C','57.8°C','22.4°C'],'(104−32)×5/9 = 40.'],['A rise of 18°F equals what Celsius rise?',['10°C','42°C','−7.8°C','32.4°C'],'For a difference, multiply by 5/9 without the offset.'],['What is 1.4 hours in hours and minutes?',['1 h 24 min','1 h 40 min','1 h 4 min','1 h 14 min'],'0.4×60 = 24 minutes.'],['What time is 90 minutes after 23:20?',['00:50 next day','00:10 next day','24:10 same day','01:20 next day'],'Forty minutes reaches midnight, then fifty minutes remain.'],['What is 6 lb 4 oz in pounds?',['6.25 lb','6.4 lb','6.04 lb','6.5 lb'],'Four ounces is 4/16 = 0.25 pound.'],['A problem specifies 20 gtt/mL. Which factor should be used?',['20 gtt/mL','15 gtt/mL because it appears in a general table','60 gtt/mL regardless of the problem','1 gtt/mL'],'Use the explicit factor supplied for the calculation.']],{t:'w',kind:'sort',title:'Keep the dimensions distinct',buckets:['Mass','Volume','Time or interval','Temperature'],items:[['Pound',0],['Weight ounce',0],['Fluid ounce',1],['Tablespoon',1],['2.5 hours',2],['45 minutes',2],['37°C',3],['A rise of 9°F',3]]});

import {MORE} from './medical-math-b.js';
for(const entry of MORE)add(...entry);
const [geometry,dosage,weightBased,essentials,metric,household,ivFlow,ivTitrated,percent,dilution]=lessons;
// Extra generated practice: new numbers every time, checked against the HOSA rounding rules.
const practice=(lesson,block)=>lesson.sections.find(([h])=>h==='Reference concepts and practice')[1].push(block);
practice(essentials,{t:'w',kind:'dosecalc',title:'Proportion practice with fresh numbers',types:['liquid'],prompt:'Write the setup and final answer on paper first, then check. Round only the final answer.'});
practice(metric,{t:'w',kind:'dosecalc',title:'Conversion drill',types:['convert'],prompt:'Predict whether the number should get larger or smaller before you calculate.'});
practice(dosage,{t:'w',kind:'dosecalc',title:'Tablets and liquids drill',types:['tablets','liquid'],prompt:'Work each problem on paper, then check. New problems appear every time.'});
practice(weightBased,{t:'w',kind:'dosecalc',title:'Weight-based drill',types:['weight'],prompt:'Remember the HOSA convention: pediatric doses are rounded down.'});
practice(ivFlow,{t:'w',kind:'dosecalc',title:'Pump and drip rate drill',types:['ivrate','drip'],prompt:'Practice both mL/h and gtt/min. Drops are reported as whole numbers.'});
practice(ivTitrated,{t:'w',kind:'dosecalc',title:'Infusion rate drill',types:['ivrate'],prompt:'Find the concentration first, then the rate.'});
practice(percent,{t:'w',kind:'mathlab',mode:'concentration',title:'From concentration to volume'});
practice(household,{t:'w',kind:'flip',title:'Household and clock equivalents',cards:[['1 tablespoon','15 mL (3 teaspoons)'],['1 fluid ounce','30 mL (2 tablespoons)'],['1 cup','240 mL (8 fluid ounces)'],['1 kg','2.2 lb'],['1 inch','2.54 cm'],['°C from °F','(°F − 32) × 5/9'],['0.75 hour','45 minutes'],['2330 + 1 h 45 min','0115 the next day']]});


export default course('Medical Math',{intro:'Ten in-depth lessons following the HOSA Medical Math 2026–27 test plan and its official reference summary: conversions, dosage, intravenous solutions, and dilutions, solutions and concentrations. Every problem shows the unit setup, the HOSA rounding conventions and an independent check. The official test uses grid-in numerical answers and a handheld calculator; practice by writing the final number and unit yourself before checking. All quantities are invented arithmetic examples, not treatment orders.',units:[
 {title:'Unit 1 · Mathematical essentials and measurement',summary:'Test plan: Mathematical essentials 5% and Measurement and conversion problems 30%. At least half of all computation problems involve conversions.',lessons:[essentials,metric,household,geometry]},
 {title:'Unit 2 · Drug dosage calculations',summary:'Test plan: Drug dosages and intravenous solutions 35%. Labels, concentrations, weight-based and BSA-based calculations.',lessons:[dosage,weightBased]},
 {title:'Unit 3 · Intravenous solutions',summary:'Flow rates in mL/h and gtt/min, infusion and finish times, and weight-based infusions.',lessons:[ivFlow,ivTitrated]},
 {title:'Unit 4 · Dilutions, solutions and concentrations',summary:'Test plan: 30%. Percent and ratio strength, preparing solutions, C₁V₁ = C₂V₂ and alligation.',lessons:[percent,dilution]},
]});
